input.command:
mkdir -p sup4 && cd sup4 && cat > total.js <<'EOF'
// Original (from ticket SUP-4)
function totalOriginal(price, taxRate) {
  return price + price * taxRate + price * taxRate;
}
// Proposed fix: apply tax once
function total(price, taxRate) {
  return price + price * taxRate;
}
module.exports = { total, totalOriginal };
EOF
cat > total.test.js <<'EOF'
const test = require('node:test');
const assert = require('node:assert');
const { total, totalOriginal } = require('./total.js');
test('original reproduces bug: total(100, 0.1) returns 120', () => {
  assert.strictEqual(totalOriginal(100, 0.1), 120);
});
test('fixed: total(100, 0.1) returns 110', () => {
  assert.strictEqual(total(100, 0.1), 110);
});
test('fixed: zero tax returns price', () => {
  assert.strictEqual(total(100, 0), 100);
});
EOF
node --version; node --test total.test.js; echo "exit=$?"

